(6204619, 916307, 42198, '<td valign="top">Nice juxtaposition with the three towers in the background, if that''s what they are.</td>', 'Nice juxtaposition with the three towers in the background, if that''s what they are.', '2010-10-29 19:37:35.000000', NULL, 1),
